if (root == nullptr) {
        return;
    }

    if (item < root->data) {
        avlDelete(root->left, item);
    } else if (item > root->data) {
        avlDelete(root->right, item);
    } else {
        if (root->left == nullptr || root->right == nullptr) {
            TreeNode* temp = root->left ? root->left : root->right;
            if (temp == nullptr) {
                temp = root;
                root = nullptr;
            } else {
                *root = *temp;
            }
            delete temp;
        } else {
            TreeNode* temp = bstFindMin(root->right);
            root->data = temp->data;
            avlDelete(root->right, temp->data);
        }
    }

    if (root == nullptr) {
        return;
    }

    int balance = bstHeight(root->left) - bstHeight(root->right);

    if (balance > 1) {
        if (bstHeight(root->left->left) >= bstHeight(root->left->right)) {
            avlRotateRight(root);
        } else {
            avlRotateLeft(root->left);
            avlRotateRight(root);
        }
    } else if (balance < -1) {
        if (bstHeight(root->right->right) >= bstHeight(root->right->left)) {
            avlRotateLeft(root);
        } else {
            avlRotateRight(root->right);
            avlRotateLeft(root);
        }
    } else {
        if (root->left) {
            root->left->height = 1 + std::max(bstHeight(root->left->left), bstHeight(root->left->right));
        }
        if (root->right) {
            root->right->height = 1 + std::max(bstHeight(root->right->left), bstHeight(root->right->right));
        }
        root->height = 1 + std::max(bstHeight(root->left), bstHeight(root->right));
    }

